from src.stockflow.first_fit_decreasing import first_fit_decreasing


def split_shipment(lines: Sequence[Tuple[str, int, int]], max_parcel_grams: int) -> List[Dict[str, int]]:
    if max_parcel_grams <= 0:
        raise ValueError("max_parcel_grams must be > 0")

    sku_to_weight: Dict[str, int] = {}
    merged_skus: Dict[str, int] = {}

    for sku, qty, unit_weight in lines:
        if qty <= 0 or unit_weight <= 0:
            raise ValueError("qty and unit_weight must be > 0")
        if unit_weight > max_parcel_grams:
            raise ValueError("single unit is heavier than max_parcel_grams")
        if sku in sku_to_weight and sku_to_weight[sku] != unit_weight:
            raise ValueError(f"SKU {sku} has different unit weights")

        sku_to_weight[sku] = unit_weight
        merged_skus[sku] = merged_skus.get(sku, 0) + qty

    items: List[Tuple[str, int]] = []
    for sku, total_qty in merged_skus.items():
        unit_weight = sku_to_weight[sku]
        total_weight = total_qty * unit_weight

        # Split the line into chunks that fit in a parcel
        remaining_qty = total_qty
        while remaining_qty > 0:
            # How many units can we fit in one parcel?
            can_fit = min(remaining_qty, max_parcel_grams // unit_weight)
            if can_fit == 0: # Should not happen due to unit_weight check
                can_fit = 1

            chunk_weight = can_fit * unit_weight
            items.append((sku, chunk_weight))
            remaining_qty -= can_fit

    bins = first_fit_decreasing(items, max_parcel_grams)

    result: List[Dict[str, int]] = []
    for b in bins:
        parcel_counts: Dict[str, int] = {}
        for sku, weight in b:
            unit_weight = sku_to_weight[sku]
            qty = weight // unit_weight
            parcel_counts[sku] = parcel_counts.get(sku, 0) + qty
        result.append(parcel_counts)
    return result
